L["UFGroupHealerBuffEditorRuleInfoBarDrainColor"] = "%s에 대한 규칙을 표시합니다. 범위는 규칙마다 설정됩니다 (파티/공격대/대상/주시 대상/우두머리). 색상은 이 목록에서 첫 번째로 활성화된 규칙을 따릅니다. 지속시간 색상 단계는 남은 오라 시간에 따라 색상을 덮어쓸 수 있습니다. 소모 애니메이션은 이 목록에서 첫 번째로 활성화된 지속시간 오라를 따릅니다. 주문 색상 재정의는 규칙별로 적용됩니다 (오른쪽 클릭으로 초기화)."
L["UFGroupHealerBuffEditorRuleInfoDefault"] = "%s의 규칙을 표시 중입니다. 범위는 규칙별로 설정됩니다 (파티/공격대/대상/주시 대상/우두머리). +로 추가하고 x로 제거하세요."
L["UFGroupHealerBuffEditorRuleInfoDefaultHint"] = "+로 규칙을 추가하고 목록의 x로 제거하세요."
L["UFGroupHealerBuffEditorRuleInfoIcon"] = "%s의 규칙을 표시 중입니다. 범위는 규칙별로 설정됩니다 (파티/공격대/대상/주시 대상/우두머리). 우선순위는 이 목록의 규칙 순서를 따릅니다."
L["UFGroupHealerBuffEditorRuleInfoIconDynamic"] = "%s의 규칙을 표시 중입니다. 범위는 규칙별로 설정됩니다 (파티/공격대/대상/주시 대상/우두머리). 활성 아이콘은 설정된 최대치까지 채워지며 자동으로 정렬됩니다."
L["UFGroupHealerBuffEditorRuleInfoSquare"] = "%s에 대한 규칙 표시 중. 범위는 규칙마다 설정됩니다 (파티/공격대/대상/주시 대상/우두머리). 우선순위는 이 목록의 규칙 순서를 따릅니다. 지속시간 색상 단계는 남은 오라 시간에 따라 색상을 덮어쓸 수 있습니다. 주문 색상 덮어쓰기는 규칙마다 적용됩니다 (우클릭으로 초기화)."
